1	import { useFocusEffect } from '@react-navigation/native';
2	import { NativeStackScreenProps } from '@react-navigation/native-stack';
3	import { Keyboard, List, X, Zap, ZapOff } from 'lucide-react-native';
4	import React, { useCallback, useEffect, useRef, useState } from 'react';
5	import {
6	  Animated,
7	  Dimensions,
8	  Easing,
9	  KeyboardAvoidingView,
10	  Platform,
11	  Pressable,
12	  StyleSheet,
13	  TextInput,
14	  View,
15	} from 'react-native';
16	import { SafeAreaView } from 'react-native-safe-area-context';
17	import {
18	  Camera,
19	  Code,
20	  useCameraDevice,
21	  useCameraPermission,
22	  useCodeScanner,
23	} from 'react-native-vision-camera';
24	import { Button, IconButton, radius, spacing, Text } from '../../../design';
25	import { findProduct, upsertProduct } from '../../../db/products';
26	import { findCanonicalProductByBarcode } from '../../../db/catalog';
27	import { useT } from '../../../i18n';
28	import { RootStackParamList } from '../../../navigation/types';
29	import { api } from '../../../sync/api';
30	import { haptic } from '../../../utils/haptics';
31	import { useTheme } from '../../../theme';
32	
33	type Props = NativeStackScreenProps<RootStackParamList, 'Scanner'>;
34	
35	// Vision-camera / ML Kit format names. Order doesn't affect decoding —
36	// every frame is tried against every requested format. Listed broadly so
37	// dense GS1-128 SSCC labels, EAN/UPC products, QR, DataMatrix all work.
38	// Product barcodes are always 1D symbologies. We deliberately do NOT
39	// scan QR / data-matrix / PDF-417 / Aztec — they're 2D codes used for
40	// things like Expo's dev-client launch QR or general-purpose URLs, and
41	// the camera would happily route those into the Receiving form as if
42	// they were barcodes (seen with `exp+field-app://expo-development-client/…`
43	// in field testing).
44	const CODE_TYPES = [
45	  'code-128',
46	  'code-39',
47	  'code-93',
48	  'codabar',
49	  'ean-13',
50	  'ean-8',
51	  'itf',
52	  'upc-a',
53	  'upc-e',
54	] as const;
55	
56	// ML Kit v4+ has strong internal confidence scoring. We no longer require
57	// a 2-read confirmation gate — that was the main cause of "I have to wave
58	// the barcode back and forth" sluggishness. A single valid decode is
59	// accepted immediately.
60	
61	export function ScannerScreen({ navigation }: Props) {
62	  const { palette } = useTheme();
63	  const t = useT();
64	  const { hasPermission, requestPermission } = useCameraPermission();
65	  const device = useCameraDevice('back');
66	  const [torch, setTorch] = useState(false);
67	  const [manualOpen, setManualOpen] = useState(false);
68	  const [manualValue, setManualValue] = useState('');
69	
70	  // acceptedRef — true while a code is being routed; blocks further reads.
71	  const acceptedRef = useRef(false);
72	
73	  // Reset on every screen focus so returning from the order session flow
74	  // allows scanning the next item without remounting the screen.
75	  useFocusEffect(
76	    useCallback(() => {
77	      acceptedRef.current = false;
78	    }, []),
79	  );
80	
81	  const flashOpacity = useRef(new Animated.Value(0)).current;
82	  const pulse = useRef(new Animated.Value(0)).current;
83	
84	  useEffect(() => {
85	    if (!hasPermission) requestPermission();
86	  }, [hasPermission, requestPermission]);
87	
88	  // Pulse the reticle border to communicate omnidirectional detection.
89	  useEffect(() => {
90	    const anim = Animated.loop(
91	      Animated.sequence([
92	        Animated.timing(pulse, {
93	          toValue: 1,
94	          duration: 900,
95	          easing: Easing.inOut(Easing.ease),
96	          useNativeDriver: true,
97	        }),
98	        Animated.timing(pulse, {
99	          toValue: 0,
100	          duration: 900,
101	          easing: Easing.inOut(Easing.ease),
102	          useNativeDriver: true,
103	        }),
104	      ]),
105	    );
106	    anim.start();
107	    return () => anim.stop();
108	  }, [pulse]);
109	
110	  const flash = useCallback(() => {
111	    flashOpacity.setValue(0.6);
112	    Animated.timing(flashOpacity, {
113	      toValue: 0,
114	      duration: 240,
115	      useNativeDriver: true,
116	    }).start();
117	  }, [flashOpacity]);
118	
119	  /**
120	   * Route a barcode to the next screen. Local catalog → Receiving;
121	   * otherwise ask the backend; final fallback is the registration flow.
122	   */
123	  const routeFor = useCallback(
124	    async (raw: string) => {
125	      // First check: canonical product catalog (barcode → product_id)
126	      const canonical = await findCanonicalProductByBarcode(raw).catch(() => null);
127	      if (canonical) {
128	        navigation.push('Receiving', {
129	          barcode: raw,
130	          productId: canonical.product_id,
131	          productName: canonical.canonical_name,
132	          unit: canonical.unit,
133	          packSize: canonical.pack_size,
134	        });
135	        return;
136	      }
137	
138	      // Second check: legacy local products table
139	      const local = await findProduct(raw).catch(() => null);
140	      if (local) {
141	        navigation.push('Receiving', {
142	          barcode: raw,
143	          packSize: local.pack_size ?? undefined,
144	        });
145	        return;
146	      }
147	
148	      // Third check: backend catalog
149	      try {
150	        const hit = await api.fetch.catalog(raw);
151	        if (hit.product) {
152	          await upsertProduct({
153	            barcode: hit.product.barcode,
154	            name: hit.product.name,
155	            category: hit.product.category,
156	            unit: hit.product.unit,
157	            pack_size: hit.product.pack_size ?? null,
158	          });
159	          navigation.push('Receiving', {
160	            barcode: raw,
161	            packSize: hit.product.pack_size ?? undefined,
162	          });
163	          return;
164	        }
165	      } catch {
166	        // Offline / 401 — fall through.
167	      }
168	
169	      // Barcode not in any catalog — go straight to the registration form
170	      // so the user can name + categorise the product. The catalog list is
171	      // surfaced inline as fuzzy suggestions on the name input itself.
172	      navigation.push('RegisterProduct', { barcode: raw });
173	    },
174	    [navigation],
175	  );
176	
177	  /** A scanned code is only a usable product barcode if it looks like
178	   *  one — UPC/EAN/ITF/Code128 are alphanumeric (mostly digits) with
179	   *  no whitespace. We already restrict the scanner to 1D code types,
180	   *  but defense in depth: also reject any URI-scheme string
181	   *  (http://, exp+field-app://, mailto:, tel:, etc.) in case a 1D
182	   *  barcode ever carried URL-like text. */
183	  const looksLikeBarcode = (raw: string): boolean => {
184	    const v = raw.trim();
185	    if (v.length < 4 || v.length > 32) return false;
186	    // Any URI scheme — "scheme:" or "scheme://" — is not a product barcode.
187	    if (/^[a-z][a-z0-9+.-]*:/i.test(v)) return false;
188	    if (/\s/.test(v)) return false;
189	    // Allow alphanumerics, dashes, underscores (covers EAN/UPC + serials).
190	    return /^[A-Za-z0-9_-]+$/.test(v);
191	  };
192	
193	  /** Entry point for both camera scans (after the 2-read gate) and manual entry. */
194	  const acceptCode = useCallback(
195	    (raw: string) => {
196	      if (acceptedRef.current) return;
197	      if (!looksLikeBarcode(raw)) {
198	        // Soft-reject: brief haptic so the user knows the read fired,
199	        // but don't navigate. The camera will detect again on the next
200	        // frame, hopefully landing on the actual product barcode.
201	        haptic.warn();
202	        return;
203	      }
204	      acceptedRef.current = true;
205	      haptic.success();
206	      flash();
207	      routeFor(raw.trim());
208	    },
209	    [flash, routeFor],
210	  );
211	
212	  const onCodeScanned = useCallback(
213	    (codes: Code[]) => {
214	      if (acceptedRef.current) return;
215	      // Accept the first code with a non-empty value immediately.
216	      // ML Kit v4+ has its own internal confidence scoring so a single
217	      // detection is reliable. The old 2-read gate added 150-300ms
218	      // latency and required the user to hold very still.
219	      const first = codes.find((c) => c.value);
220	      if (!first?.value) return;
221	      acceptCode(first.value);
222	    },
223	    [acceptCode],
224	  );
225	
226	  const codeScanner = useCodeScanner({
227	    codeTypes: [...CODE_TYPES],
228	    onCodeScanned,
229	  });
230	
231	  const submitManual = useCallback(() => {
232	    const v = manualValue.trim();
233	    if (!v) return;
234	    // Apply the same shape check as camera scans — paste-from-clipboard
235	    // or autofill can drop a URL into the manual field too.
236	    if (!looksLikeBarcode(v)) {
237	      haptic.warn();
238	      return;
239	    }
240	    setManualOpen(false);
241	    setManualValue('');
242	    if (acceptedRef.current) return;
243	    acceptedRef.current = true;
244	    haptic.success();
245	    routeFor(v);
246	  }, [manualValue, routeFor]);
247	
248	  const pulseScale = pulse.interpolate({ inputRange: [0, 1], outputRange: [1, 1.04] });
249	  const pulseOpacity = pulse.interpolate({ inputRange: [0, 1], outputRange: [0.55, 1] });
250	
251	  if (!hasPermission) {
252	    return (
253	      <SafeAreaView style={[styles.permission, { backgroundColor: palette.background }]}>
254	        <Text variant="headlineSmall" style={{ textAlign: 'center', marginBottom: spacing.md }}>
255	          {t('cameraNeeded')}
256	        </Text>
257	        <Text
258	          variant="bodyLarge"
259	          color={palette.onSurfaceVariant}
260	          style={{ textAlign: 'center', marginBottom: spacing.xl }}
261	        >
262	          {t('cameraHint')}
263	        </Text>
264	        <Button label={t('allowCamera')} onPress={requestPermission} size="lg" fullWidth />
265	        <Button
266	          label={t('notNow')}
267	          variant="text"
268	          onPress={() => navigation.goBack()}
269	          style={{ marginTop: spacing.sm }}
270	        />
271	      </SafeAreaView>
272	    );
273	  }
274	
275	  if (!device) {
276	    return (
277	      <SafeAreaView style={[styles.permission, { backgroundColor: palette.background }]}>
278	        <Text variant="headlineSmall" style={{ textAlign: 'center' }}>
279	          {t('noCamera')}
280	        </Text>
281	        <Button
282	          label={t('back')}
283	          variant="text"
284	          onPress={() => navigation.goBack()}
285	          style={{ marginTop: spacing.md }}
286	        />
287	      </SafeAreaView>
288	    );
289	  }
290	
291	  return (
292	    <View style={styles.root}>
293	      <Camera
294	        style={StyleSheet.absoluteFill}
295	        device={device}
296	        isActive
297	        torch={torch ? 'on' : 'off'}
298	        codeScanner={codeScanner}
299	        resizeMode="cover"
300	      />
301	
302	      {/* Dimmed border around the reticle. Pure cosmetics — detection
303	          is full-frame, so this is just a "look here" hint. */}
304	      <View pointerEvents="none" style={styles.maskTop} />
305	      <View pointerEvents="none" style={styles.maskRow}>
306	        <View style={styles.maskSide} />
307	        <View style={styles.window}>
308	          <Animated.View
309	            pointerEvents="none"
310	            style={[
311	              styles.reticle,
312	              {
313	                opacity: pulseOpacity,
314	                transform: [{ scale: pulseScale }],
315	                borderColor: palette.primaryContainer,
316	              },
317	            ]}
318	          />
319	        </View>
320	        <View style={styles.maskSide} />
321	      </View>
322	      <View pointerEvents="none" style={styles.maskBottom} />
323	
324	      <Animated.View pointerEvents="none" style={[styles.flash, { opacity: flashOpacity }]} />
325	
326	      <SafeAreaView edges={['top']} style={styles.topBar}>
327	        <View style={styles.topBarRow}>
328	          <IconButton Icon={X} onPress={() => navigation.goBack()} tone="inverse" />
329	          <Text variant="titleMedium" color="#fff">
330	            Scan barcode
331	          </Text>
332	          <IconButton
333	            Icon={torch ? Zap : ZapOff}
334	            onPress={() => setTorch((t) => !t)}
335	            tone="inverse"
336	          />
337	        </View>
338	      </SafeAreaView>
339	
340	      <SafeAreaView edges={['bottom']} style={styles.bottom}>
341	        <Text
342	          variant="bodyLarge"
343	          color="#fff"
344	          style={{ textAlign: 'center', paddingHorizontal: spacing.xl }}
345	        >
346	          Hold the barcode steady for a moment.
347	        </Text>
348	        <Pressable
349	          onPress={() => setManualOpen(true)}
350	          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
351	          style={({ pressed }) => [
352	            styles.typeBtn,
353	            { backgroundColor: pressed ? '#ffffff22' : '#ffffff11' },
354	          ]}
355	        >
356	          <Keyboard size={18} color="#fff" strokeWidth={2.2} />
357	          <Text variant="labelLarge" color="#fff">
358	            Type code
359	          </Text>
360	        </Pressable>
361	        <Pressable
362	          onPress={() => {
363	            if (acceptedRef.current) return;
364	            acceptedRef.current = true;
365	            haptic.tap();
366	            navigation.push('CatalogPicker', { barcode: undefined });
367	          }}
368	          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
369	          style={({ pressed }) => [
370	            styles.typeBtn,
371	            { backgroundColor: pressed ? '#ffffff22' : '#ffffff11', marginTop: spacing.sm },
372	          ]}
373	        >
374	          <List size={18} color="#fff" strokeWidth={2.2} />
375	          <Text variant="labelLarge" color="#fff">
376	            No barcode
377	          </Text>
378	        </Pressable>
379	      </SafeAreaView>
380	
381	      {manualOpen && (
382	        <Pressable style={styles.modalBackdrop} onPress={() => setManualOpen(false)}>
383	          <KeyboardAvoidingView
384	            behavior={Platform.OS === 'ios' ? 'padding' : undefined}
385	            style={styles.modalCenter}
386	            pointerEvents="box-none"
387	          >
388	            <Pressable
389	              onPress={(e) => e.stopPropagation()}
390	              style={[styles.modalCard, { backgroundColor: palette.surface }]}
391	            >
392	              <Text variant="titleLarge">Type the barcode</Text>
393	              <Text
394	                variant="bodyMedium"
395	                color={palette.onSurfaceVariant}
396	                style={{ marginTop: spacing.xs }}
397	              >
398	                Use this when the label is damaged or won't scan.
399	              </Text>
400	              <TextInput
401	                value={manualValue}
402	                onChangeText={setManualValue}
403	                placeholder={t('barcodeExample')}
404	                placeholderTextColor={palette.onSurfaceVariant}
405	                keyboardType="number-pad"
406	                autoFocus
407	                returnKeyType="done"
408	                onSubmitEditing={submitManual}
409	                style={[
410	                  styles.modalInput,
411	                  {
412	                    backgroundColor: palette.surfaceContainerLowest,
413	                    borderColor: palette.outlineVariant,
414	                    color: palette.onSurface,
415	                  },
416	                ]}
417	              />
418	              <View style={styles.modalActions}>
419	                <Button
420	                  label={t('cancel')}
421	                  variant="text"
422	                  size="md"
423	                  onPress={() => setManualOpen(false)}
424	                />
425	                <Button
426	                  label={t('useCode')}
427	                  size="md"
428	                  disabled={manualValue.trim().length === 0}
429	                  onPress={submitManual}
430	                />
431	              </View>
432	            </Pressable>
433	          </KeyboardAvoidingView>
434	        </Pressable>
435	      )}
436	    </View>
437	  );
438	}
439	
440	// Reticle covers most of the screen width so the user has plenty of room
441	// to frame a barcode at any rotation. Detection is full-frame regardless —
442	// the reticle is purely a "look here" hint.
443	const WINDOW = Math.min(Dimensions.get('window').width - 24, 400);
444	
445	const styles = StyleSheet.create({
446	  root: { flex: 1, backgroundColor: '#000' },
447	  permission: {
448	    flex: 1,
449	    padding: spacing.xl,
450	    justifyContent: 'center',
451	  },
