import { useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { Keyboard, List, X, Zap, ZapOff } from 'lucide-react-native';
import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  Animated,
  Dimensions,
  Easing,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  StyleSheet,
  TextInput,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import {
  Camera,
  Code,
  useCameraDevice,
  useCameraPermission,
  useCodeScanner,
} from 'react-native-vision-camera';
import { Button, IconButton, radius, spacing, Text } from '../../../design';
import { findProduct, upsertProduct } from '../../../db/products';
import { findCanonicalProductByBarcode } from '../../../db/catalog';
import { useT } from '../../../i18n';
import { RootStackParamList } from '../../../navigation/types';
import { api } from '../../../sync/api';
import { haptic } from '../../../utils/haptics';
import { useTheme } from '../../../theme';

type Props = NativeStackScreenProps<RootStackParamList, 'Scanner'>;

// Vision-camera / ML Kit format names. Order doesn't affect decoding —
// every frame is tried against every requested format. Listed broadly so
// dense GS1-128 SSCC labels, EAN/UPC products, QR, DataMatrix all work.
// Product barcodes are always 1D symbologies. We deliberately do NOT
// scan QR / data-matrix / PDF-417 / Aztec — they're 2D codes used for
// things like Expo's dev-client launch QR or general-purpose URLs, and
// the camera would happily route those into the Receiving form as if
// they were barcodes (seen with `exp+field-app://expo-development-client/…`
// in field testing).
const CODE_TYPES = [
  'code-128',
  'code-39',
  'code-93',
  'codabar',
  'ean-13',
  'ean-8',
  'itf',
  'upc-a',
  'upc-e',
] as const;

// ML Kit v4+ has strong internal confidence scoring. We no longer require
// a 2-read confirmation gate — that was the main cause of "I have to wave
// the barcode back and forth" sluggishness. A single valid decode is
// accepted immediately.

export function ScannerScreen({ navigation }: Props) {
  const { palette } = useTheme();
  const t = useT();
  const { hasPermission, requestPermission } = useCameraPermission();
  const device = useCameraDevice('back');
  const [torch, setTorch] = useState(false);
  const [manualOpen, setManualOpen] = useState(false);
  const [manualValue, setManualValue] = useState('');

  // acceptedRef — true while a code is being routed; blocks further reads.
  const acceptedRef = useRef(false);

  // Reset on every screen focus so returning from the order session flow
  // allows scanning the next item without remounting the screen.
  useFocusEffect(
    useCallback(() => {
      acceptedRef.current = false;
    }, []),
  );

  const flashOpacity = useRef(new Animated.Value(0)).current;
  const pulse = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (!hasPermission) requestPermission();
  }, [hasPermission, requestPermission]);

  // Pulse the reticle border to communicate omnidirectional detection.
  useEffect(() => {
    const anim = Animated.loop(
      Animated.sequence([
        Animated.timing(pulse, {
          toValue: 1,
          duration: 900,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
        Animated.timing(pulse, {
          toValue: 0,
          duration: 900,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
      ]),
    );
    anim.start();
    return () => anim.stop();
  }, [pulse]);

  const flash = useCallback(() => {
    flashOpacity.setValue(0.6);
    Animated.timing(flashOpacity, {
      toValue: 0,
      duration: 240,
      useNativeDriver: true,
    }).start();
  }, [flashOpacity]);

  /**
   * Route a barcode to the next screen. Local catalog → Receiving;
   * otherwise ask the backend; final fallback is the registration flow.
   */
  const routeFor = useCallback(
    async (raw: string) => {
      // First check: canonical product catalog (barcode → product_id)
      const canonical = await findCanonicalProductByBarcode(raw).catch(() => null);
      if (canonical) {
        navigation.push('Receiving', {
          barcode: raw,
          productId: canonical.product_id,
          productName: canonical.canonical_name,
          unit: canonical.unit,
          packSize: canonical.pack_size,
        });
        return;
      }

      // Second check: legacy local products table
      const local = await findProduct(raw).catch(() => null);
      if (local) {
        navigation.push('Receiving', {
          barcode: raw,
          packSize: local.pack_size ?? undefined,
        });
        return;
      }

      // Third check: backend catalog
      try {
        const hit = await api.fetch.catalog(raw);
        if (hit.product) {
          await upsertProduct({
            barcode: hit.product.barcode,
            name: hit.product.name,
            category: hit.product.category,
            unit: hit.product.unit,
            pack_size: hit.product.pack_size ?? null,
          });
          navigation.push('Receiving', {
            barcode: raw,
            packSize: hit.product.pack_size ?? undefined,
          });
          return;
        }
      } catch {
        // Offline / 401 — fall through.
      }

      // Barcode not in any catalog — go straight to the registration form
      // so the user can name + categorise the product. The catalog list is
      // surfaced inline as fuzzy suggestions on the name input itself.
      navigation.push('RegisterProduct', { barcode: raw });
    },
    [navigation],
  );

  /** A scanned code is only a usable product barcode if it looks like
   *  one — UPC/EAN/ITF/Code128 are alphanumeric (mostly digits) with
   *  no whitespace. We already restrict the scanner to 1D code types,
   *  but defense in depth: also reject any URI-scheme string
   *  (http://, exp+field-app://, mailto:, tel:, etc.) in case a 1D
   *  barcode ever carried URL-like text. */
  const looksLikeBarcode = (raw: string): boolean => {
    const v = raw.trim();
    if (v.length < 4 || v.length > 32) return false;
    // Any URI scheme — "scheme:" or "scheme://" — is not a product barcode.
    if (/^[a-z][a-z0-9+.-]*:/i.test(v)) return false;
    if (/\s/.test(v)) return false;
    // Allow alphanumerics, dashes, underscores (covers EAN/UPC + serials).
    return /^[A-Za-z0-9_-]+$/.test(v);
  };

  /** Entry point for both camera scans (after the 2-read gate) and manual entry. */
  const acceptCode = useCallback(
    (raw: string) => {
      if (acceptedRef.current) return;
      if (!looksLikeBarcode(raw)) {
        // Soft-reject: brief haptic so the user knows the read fired,
        // but don't navigate. The camera will detect again on the next
        // frame, hopefully landing on the actual product barcode.
        haptic.warn();
        return;
      }
      acceptedRef.current = true;
      haptic.success();
      flash();
      routeFor(raw.trim());
    },
    [flash, routeFor],
  );

  const onCodeScanned = useCallback(
    (codes: Code[]) => {
      if (acceptedRef.current) return;
      // Accept the first code with a non-empty value immediately.
      // ML Kit v4+ has its own internal confidence scoring so a single
      // detection is reliable. The old 2-read gate added 150-300ms
      // latency and required the user to hold very still.
      const first = codes.find((c) => c.value);
      if (!first?.value) return;
      acceptCode(first.value);
    },
    [acceptCode],
  );

  const codeScanner = useCodeScanner({
    codeTypes: [...CODE_TYPES],
    onCodeScanned,
  });

  const submitManual = useCallback(() => {
    const v = manualValue.trim();
    if (!v) return;
    // Apply the same shape check as camera scans — paste-from-clipboard
    // or autofill can drop a URL into the manual field too.
    if (!looksLikeBarcode(v)) {
      haptic.warn();
      return;
    }
    setManualOpen(false);
    setManualValue('');
    if (acceptedRef.current) return;
    acceptedRef.current = true;
    haptic.success();
    routeFor(v);
  }, [manualValue, routeFor]);

  const pulseScale = pulse.interpolate({ inputRange: [0, 1], outputRange: [1, 1.04] });
  const pulseOpacity = pulse.interpolate({ inputRange: [0, 1], outputRange: [0.55, 1] });

  if (!hasPermission) {
    return (
      <SafeAreaView style={[styles.permission, { backgroundColor: palette.background }]}>
        <Text variant="headlineSmall" style={{ textAlign: 'center', marginBottom: spacing.md }}>
          {t('cameraNeeded')}
        </Text>
        <Text
          variant="bodyLarge"
          color={palette.onSurfaceVariant}
          style={{ textAlign: 'center', marginBottom: spacing.xl }}
        >
          {t('cameraHint')}
        </Text>
        <Button label={t('allowCamera')} onPress={requestPermission} size="lg" fullWidth />
        <Button
          label={t('notNow')}
          variant="text"
          onPress={() => navigation.goBack()}
          style={{ marginTop: spacing.sm }}
        />
      </SafeAreaView>
    );
  }

  if (!device) {
    return (
      <SafeAreaView style={[styles.permission, { backgroundColor: palette.background }]}>
        <Text variant="headlineSmall" style={{ textAlign: 'center' }}>
          {t('noCamera')}
        </Text>
        <Button
          label={t('back')}
          variant="text"
          onPress={() => navigation.goBack()}
          style={{ marginTop: spacing.md }}
        />
      </SafeAreaView>
    );
  }

  return (
    <View style={styles.root}>
      <Camera
        style={StyleSheet.absoluteFill}
        device={device}
        isActive
        torch={torch ? 'on' : 'off'}
        codeScanner={codeScanner}
        resizeMode="cover"
      />

      {/* Dimmed border around the reticle. Pure cosmetics — detection
          is full-frame, so this is just a "look here" hint. */}
      <View pointerEvents="none" style={styles.maskTop} />
      <View pointerEvents="none" style={styles.maskRow}>
        <View style={styles.maskSide} />
        <View style={styles.window}>
          <Animated.View
            pointerEvents="none"
            style={[
              styles.reticle,
              {
                opacity: pulseOpacity,
                transform: [{ scale: pulseScale }],
                borderColor: palette.primaryContainer,
              },
            ]}
          />
        </View>
        <View style={styles.maskSide} />
      </View>
      <View pointerEvents="none" style={styles.maskBottom} />

      <Animated.View pointerEvents="none" style={[styles.flash, { opacity: flashOpacity }]} />

      <SafeAreaView edges={['top']} style={styles.topBar}>
        <View style={styles.topBarRow}>
          <IconButton Icon={X} onPress={() => navigation.goBack()} tone="inverse" />
          <Text variant="titleMedium" color="#fff">
            Scan barcode
          </Text>
          <IconButton
            Icon={torch ? Zap : ZapOff}
            onPress={() => setTorch((t) => !t)}
            tone="inverse"
          />
        </View>
      </SafeAreaView>

      <SafeAreaView edges={['bottom']} style={styles.bottom}>
        <Text
          variant="bodyLarge"
          color="#fff"
          style={{ textAlign: 'center', paddingHorizontal: spacing.xl }}
        >
          Hold the barcode steady for a moment.
        </Text>
        <Pressable
          onPress={() => setManualOpen(true)}
          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
          style={({ pressed }) => [
            styles.typeBtn,
            { backgroundColor: pressed ? '#ffffff22' : '#ffffff11' },
          ]}
        >
          <Keyboard size={18} color="#fff" strokeWidth={2.2} />
          <Text variant="labelLarge" color="#fff">
            Type code
          </Text>
        </Pressable>
        <Pressable
          onPress={() => {
            if (acceptedRef.current) return;
            acceptedRef.current = true;
            haptic.tap();
            navigation.push('CatalogPicker', { barcode: undefined });
          }}
          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
          style={({ pressed }) => [
            styles.typeBtn,
            { backgroundColor: pressed ? '#ffffff22' : '#ffffff11', marginTop: spacing.sm },
          ]}
        >
          <List size={18} color="#fff" strokeWidth={2.2} />
          <Text variant="labelLarge" color="#fff">
            No barcode
          </Text>
        </Pressable>
      </SafeAreaView>

      {manualOpen && (
        <Pressable style={styles.modalBackdrop} onPress={() => setManualOpen(false)}>
          <KeyboardAvoidingView
            behavior={Platform.OS === 'ios' ? 'padding' : undefined}
            style={styles.modalCenter}
            pointerEvents="box-none"
          >
            <Pressable
              onPress={(e) => e.stopPropagation()}
              style={[styles.modalCard, { backgroundColor: palette.surface }]}
            >
              <Text variant="titleLarge">Type the barcode</Text>
              <Text
                variant="bodyMedium"
                color={palette.onSurfaceVariant}
                style={{ marginTop: spacing.xs }}
              >
                Use this when the label is damaged or won't scan.
              </Text>
              <TextInput
                value={manualValue}
                onChangeText={setManualValue}
                placeholder={t('barcodeExample')}
                placeholderTextColor={palette.onSurfaceVariant}
                keyboardType="number-pad"
                autoFocus
                returnKeyType="done"
                onSubmitEditing={submitManual}
                style={[
                  styles.modalInput,
                  {
                    backgroundColor: palette.surfaceContainerLowest,
                    borderColor: palette.outlineVariant,
                    color: palette.onSurface,
                  },
                ]}
              />
              <View style={styles.modalActions}>
                <Button
                  label={t('cancel')}
                  variant="text"
                  size="md"
                  onPress={() => setManualOpen(false)}
                />
                <Button
                  label={t('useCode')}
                  size="md"
                  disabled={manualValue.trim().length === 0}
                  onPress={submitManual}
                />
              </View>
            </Pressable>
          </KeyboardAvoidingView>
        </Pressable>
      )}
    </View>
  );
}

